#include <iostream>
using namespace std;

class MeowCat {
protected:
    int times;
public:
    MeowCat(int k) : times(k) { cout << "搭那份共用的底座：" << times << endl; }
    void meow() const { cout << "喵 " << times << " {unit}" << endl; }
};

class Purr : virtual public MeowCat {
public:
    Purr(int k) : MeowCat(k) { cout << "搭会打呼噜的那一半" << endl; }
    void purr() const { cout << "呼噜 " << times << " {unit}" << endl; }
};

class Knead : virtual public MeowCat {
public:
    Knead(int k) : MeowCat(k) { cout << "搭会踩奶的那一半" << endl; }
    void knead() const { cout << "踩奶 " << times << " {unit}" << endl; }
};

class Baby : public Purr, public Knead {
public:
    Baby(int k) : MeowCat(k), Purr(k), Knead(k) {}
};

int main() {
    int n = 0;
    cin >> n;

    Baby b(n);
    b.meow();
    b.purr();
    b.knead();
    return 0;
}
